using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using PA.Tickets.Application.Tickets;using PA.Tickets.Domain.Tickets;using PA.Tickets.Infrastructure.Persistence;
namespace PA.Tickets.Infrastructure.Tickets;
public sealed class OracleTicketIdentityGenerator(TicketsDbContext db):ITicketIdentityGenerator{public async Task<(long Id,string Number)> NextAsync(TicketType type,CancellationToken ct){var id=await Scalar("PA_TICKETS_SEQ.NEXTVAL",ct);var no=await Scalar("PA_TICKETS_TICKET_NO_SEQ.NEXTVAL",ct);var code=type switch{TicketType.Request=>"REQ",TicketType.Incident=>"INC",TicketType.Problem=>"PRB",TicketType.Task=>"TSK",TicketType.Change=>"CHG",_=>"TKT"};return(id,$"{code}-{no:D6}");}public Task<long> NextWorkItemIdAsync(CancellationToken ct)=>Scalar("PA_TICKETS_WORK_ITEM_SEQ.NEXTVAL",ct);private async Task<long> Scalar(string expression,CancellationToken ct){await db.Database.OpenConnectionAsync(ct);try{await using var command=db.Database.GetDbConnection().CreateCommand();command.CommandText=$"SELECT {expression} FROM DUAL";return Convert.ToInt64(await command.ExecuteScalarAsync(ct));}finally{await db.Database.CloseConnectionAsync();}}}
public sealed class PostgreSqlTicketIdentityGenerator(TicketsDbContext db):ITicketIdentityGenerator{public async Task<(long Id,string Number)> NextAsync(TicketType type,CancellationToken ct){var id=await Scalar("PA_TICKETS_SEQ",ct);var no=await Scalar("PA_TICKETS_TICKET_NO_SEQ",ct);var code=type switch{TicketType.Request=>"REQ",TicketType.Incident=>"INC",TicketType.Problem=>"PRB",TicketType.Task=>"TSK",TicketType.Change=>"CHG",_=>"TKT"};return(id,$"{code}-{no:D6}");}public Task<long> NextWorkItemIdAsync(CancellationToken ct)=>Scalar("PA_TICKETS_WORK_ITEM_SEQ",ct);private async Task<long> Scalar(string sequenceName,CancellationToken ct){await db.Database.OpenConnectionAsync(ct);try{await using var command=db.Database.GetDbConnection().CreateCommand();command.CommandText=$"select nextval('\"{sequenceName}\"'::regclass)";return Convert.ToInt64(await command.ExecuteScalarAsync(ct));}finally{await db.Database.CloseConnectionAsync();}}}
public sealed class ServerTicketAccessAuthorizer:ITicketAccessAuthorizer{public Task EnsureCanMutateAsync(long actorUserId,Ticket ticket,CancellationToken ct){if(actorUserId<=0)throw new UnauthorizedAccessException("A server-authenticated actor is required.");return Task.CompletedTask;}public Task EnsureCanAccessAsync(long actorUserId,Ticket ticket,CancellationToken ct){if(actorUserId<=0)throw new UnauthorizedAccessException("A server-authenticated actor is required.");return Task.CompletedTask;}public Task EnsureCanSearchAsync(long actorUserId,CancellationToken ct){if(actorUserId<=0)throw new UnauthorizedAccessException("A server-authenticated actor is required.");return Task.CompletedTask;}}
public sealed class ConfigurationTicketRelationshipPolicy(IConfiguration configuration):ITicketRelationshipPolicy{public bool IsAllowed(TicketType source,TicketType target,string relationType){var allowed=configuration.GetSection("Relationships:Allowed").Get<string[]>()??[];return allowed.Contains($"{source}:{target}:{relationType}",StringComparer.OrdinalIgnoreCase);}}
